\title{The M\"obius Discriminant: An Exact Sign-and-Size Law for the
Log-Behaviour of First-Order Multiplicative Recurrences}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We study positive real sequences $a:\N\to\R$ governed by a first-order
multiplicative recurrence $(\alpha n + \beta)\,a(n+1) = (\gamma n + \delta)\,a(n)$,
and attach to each such recurrence a single scalar invariant, the \emph{M\"obius
discriminant} $\Delta = \gamma\beta - \alpha\delta$. We prove that the sign of
$\Delta$ completely governs the log-behaviour of the sequence: strict
log-convexity when $\Delta>0$, exact log-linearity when $\Delta=0$, strict
log-concavity when $\Delta<0$. We upgrade this sign law to an exact quantitative
law: the pointwise discriminant $D(n)=a(n)a(n+2)-a(n+1)^2$ satisfies
$(\alpha n+\beta)(\alpha(n+1)+\beta)\,D(n)=\Delta\cdot a(n)a(n+1)$, a pure
algebraic consequence of the recurrence. The consecutive ratio is a M\"obius
transform of $n$ whose forward difference has the constant numerator $\Delta$,
and the log-curvature admits the closed form
$\log(1+\Delta/((\gamma n+\delta)(\alpha(n+1)+\beta)))$, which tends to $0$ when
$\alpha,\gamma>0$. The classical totals $2^n$ ($\Delta=0$), reciprocal
factorials ($\Delta=-1$), factorials ($\Delta=1$), central binomials
($\Delta=2$), and Catalan numbers ($\Delta=6$) realize all three regimes.
Finally, we prove that no discriminant built solely from the coefficients of a
second-order recurrence can govern log-convexity, the obstruction being the
Fibonacci numbers, whose constant-coefficient recurrence carries the
sign-alternating Cassini discriminant $(-1)^{n+1}$.
\end{abstract}

\maketitle

\section{Introduction}

A remarkable number of the sequences that combinatorics cares about are
holonomic of the simplest kind: each term is obtained from its predecessor by
multiplication by a ratio of two affine functions of the index. Powers of two,
factorials, reciprocal factorials, central binomial coefficients, and Catalan
numbers all fall into this class. Writing the multiplier as a fraction,
\[
\frac{a(n+1)}{a(n)} = \frac{\gamma n + \delta}{\alpha n + \beta},
\qquad\text{i.e.}\qquad
(\alpha n + \beta)\,a(n+1) = (\gamma n + \delta)\,a(n). \tag{$\ast$}
\]
The four real coefficients $\alpha,\beta,\gamma,\delta$ encode the entire growth
law. We show that the \emph{M\"obius discriminant}
\[
\Delta = \gamma\beta - \alpha\delta
\]
governs, exactly and pointwise, the logarithmic behaviour of the sequence, and
we delimit precisely how far this phenomenon extends. The name is deliberate:
$x\mapsto \frac{\gamma x+\delta}{\alpha x+\beta}$ is a M\"obius transformation
and $\gamma\beta-\alpha\delta$ is its determinant (up to sign).

A positive sequence $a$ is \emph{log-convex} if $a(n)a(n+2)\ge a(n+1)^2$,
\emph{log-concave} if $a(n)a(n+2)\le a(n+1)^2$, and \emph{log-linear} if equality
holds. The detector is the pointwise discriminant $D(n)=a(n)a(n+2)-a(n+1)^2$.

\section{Setup and definitions}

\begin{definition}[Recurrence class]
$a:\N\to\R$ obeys the first-order multiplicative recurrence with data
$(\alpha,\beta,\gamma,\delta)$ if $(\ast)$ holds for all $n\in\N$.
\end{definition}

\begin{definition}[M\"obius discriminant]
$\Delta = \gamma\beta - \alpha\delta$.
\end{definition}

\begin{definition}[Pointwise discriminant]
$D(n) = a(n)\,a(n+2) - a(n+1)^2$.
\end{definition}

We use: \textbf{(P)} $a(n)>0$; \textbf{(D)} $\alpha n+\beta>0$; \textbf{(N)}
$\gamma n+\delta>0$, for all $n$.

\section{The exact discriminant identity and the sign trichotomy}

\begin{theorem}[Exact discriminant identity]\label{thm:exact}
If $a$ obeys $(\ast)$ then for all $n$,
\[
(\alpha n + \beta)\,(\alpha(n+1)+\beta)\,\bigl(a(n)a(n+2)-a(n+1)^2\bigr)
= (\gamma\beta - \alpha\delta)\,a(n)\,a(n+1).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $(\ast)$ at $n$ and at $n+1$. Multiply the second relation by
$a(n)(\alpha n+\beta)$ and the first by $(\alpha(n+1)+\beta)a(n+1)$, then
subtract. The left side collects into
$(\alpha n+\beta)(\alpha(n+1)+\beta)D(n)$. On the right, substituting
$(\alpha n+\beta)a(n+1)=(\gamma n+\delta)a(n)$ to remove the residual $a(n+1)$,
the coefficient becomes
$(\gamma(n+1)+\delta)(\alpha n+\beta)-(\gamma n+\delta)(\alpha(n+1)+\beta)
=\gamma\beta-\alpha\delta$, times $a(n)a(n+1)$. This is a polynomial identity,
so no positivity is used.
\end{proof}

\begin{theorem}[Sign trichotomy]\label{thm:tri}
Assume \textup{(P)} and \textup{(D)}. Then for all $n$: $D(n)>0$ if $\Delta>0$;
$D(n)=0$ if $\Delta=0$; $D(n)<0$ if $\Delta<0$.
\end{theorem}

\begin{proof}[Proof sketch]
By (D), $P_n:=(\alpha n+\beta)(\alpha(n+1)+\beta)>0$; by (P),
$a(n)a(n+1)>0$. Theorem~\ref{thm:exact} gives $P_n D(n)=\Delta\,a(n)a(n+1)$, so
$\sgn D(n)=\sgn\Delta$.
\end{proof}

\section{The M\"obius ratio and its constant-numerator forward difference}

\begin{theorem}[Ratio as M\"obius transform]\label{thm:ratio}
Assume \textup{(P)} and \textup{(D)}. Then
$\dfrac{a(m+1)}{a(m)} = \dfrac{\gamma m + \delta}{\alpha m + \beta}$ for all $m$.
\end{theorem}

\begin{proof}[Proof sketch]
Cross-multiplying reduces to $(\ast)$; positivity makes both denominators
nonzero.
\end{proof}

\begin{theorem}[Constant-numerator forward difference]\label{thm:fdiff}
Assume \textup{(P)} and \textup{(D)}. Then for all $n$,
\[
\frac{a(n+2)}{a(n+1)} - \frac{a(n+1)}{a(n)}
= \frac{\gamma\beta - \alpha\delta}{(\alpha n + \beta)(\alpha(n+1)+\beta)}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Substitute Theorem~\ref{thm:ratio} at $n$ and $n+1$ and combine over the common
denominator; the numerator collapses to the index-independent
$\gamma\beta-\alpha\delta$.
\end{proof}

\section{The exact curvature law}

\begin{theorem}[Exact curvature ratio]\label{thm:curv}
Assume \textup{(P)}, \textup{(D)}, \textup{(N)}. Then for all $n$,
\[
\frac{a(n)\,a(n+2)}{a(n+1)^2}
= 1 + \frac{\gamma\beta - \alpha\delta}{(\gamma n + \delta)(\alpha(n+1)+\beta)}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
From Theorem~\ref{thm:exact}, $a(n)a(n+2)=a(n+1)^2+\Delta a(n)a(n+1)/P_n$.
Divide by $a(n+1)^2$ and use $a(n)/a(n+1)=(\alpha n+\beta)/(\gamma n+\delta)$
from Theorem~\ref{thm:ratio}; the correction simplifies to the stated fraction.
\end{proof}

\begin{theorem}[Log-curvature identity]\label{thm:logcurv}
Assume \textup{(P)}, \textup{(D)}, \textup{(N)}. Then for all $n$,
\[
\log a(n) - 2\log a(n+1) + \log a(n+2)
= \log\!\left(1 + \frac{\gamma\beta - \alpha\delta}{(\gamma n + \delta)(\alpha(n+1)+\beta)}\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The left side is $\log(a(n)a(n+2)/a(n+1)^2)$; apply Theorem~\ref{thm:curv}.
\end{proof}

\begin{theorem}[Asymptotic affinity of the valuation]\label{thm:flat}
Assume \textup{(P)}, \textup{(D)}, \textup{(N)}, $\alpha>0$, $\gamma>0$. Then
\[
\lim_{n\to\infty}\bigl(\log a(n) - 2\log a(n+1) + \log a(n+2)\bigr) = 0.
\]
\end{theorem}

\begin{proof}[Proof sketch]
With $\alpha,\gamma>0$ the product $(\gamma n+\delta)(\alpha(n+1)+\beta)\to
+\infty$, so the correction term tends to $0$, the argument of the logarithm
tends to $1$, and by continuity the log-curvature tends to $\log 1 = 0$.
\end{proof}

\section{The classical totals, classified}

\begin{center}
\begin{tabular}{lcccc}
\toprule
Sequence & $a(n+1)/a(n)$ & $(\alpha,\beta,\gamma,\delta)$ & $\Delta$ & Regime \\
\midrule
$2^n$ & $2$ & $(0,1,0,2)$ & $0$ & log-linear \\
$1/n!$ & $1/(n+1)$ & $(1,1,0,1)$ & $-1$ & log-concave \\
$n!$ & $n+1$ & $(0,1,1,1)$ & $+1$ & log-convex \\
$\binom{2n}{n}$ & $2(2n+1)/(n+1)$ & $(1,1,4,2)$ & $+2$ & log-convex \\
$C_n$ & $2(2n+1)/(n+2)$ & $(1,2,4,2)$ & $+6$ & log-convex \\
\bottomrule
\end{tabular}
\end{center}

\begin{theorem}[Exact Catalan discriminant identity]\label{thm:cat}
For all $n$, $\;(n+2)(n+3)\bigl(C_nC_{n+2}-C_{n+1}^2\bigr) = 6\,C_nC_{n+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
The Catalan numbers obey $(n+2)C_{n+1}=2(2n+1)C_n$, i.e. $(\ast)$ with
$(\alpha,\beta,\gamma,\delta)=(1,2,4,2)$, so $\Delta=4\cdot2-1\cdot2=6$.
Positivity and $\alpha n+\beta=n+2>0$ supply (P), (D). Apply
Theorem~\ref{thm:exact}.
\end{proof}

\section{The boundary: no coefficient-only second-order discriminant}

\begin{theorem}[Cassini-type discriminant]\label{thm:cassini}
For the Fibonacci numbers $F_n$ \textup(with $F_0=0,F_1=1$\textup),
$F_nF_{n+2}-F_{n+1}^2=(-1)^{n+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $n$ using $F_{n+2}=F_{n+1}+F_n$; this is Cassini's identity.
\end{proof}

\begin{theorem}[No coefficient-only $\Delta_2$]\label{thm:no}
There is no function of the coefficients $p,q,r$ of a second-order recurrence
$p\,a(n+2)=q\,a(n+1)+r\,a(n)$ whose sign governs the sign of
$D(n)=a(n)a(n+2)-a(n+1)^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Fibonacci obeys the recurrence with constant coefficients $p=q=r=1$; any quantity
built from those alone is a fixed constant of one sign. But by
Theorem~\ref{thm:cassini}, $D(n)=(-1)^{n+1}$ is $+1$ infinitely often and $-1$
infinitely often. No constant can be both signs.
\end{proof}

\section{Discussion and future directions}

Log-convexity and log-concavity drive unimodality, Newton-type inequalities, and
the analytic behaviour of generating functions; the M\"obius discriminant turns
these checks into a one-line computation for the entire first-order class.
Theorem~\ref{thm:flat} shows every such total is eventually geometric with a
curvature defect of order $1/n^2$ scaled by $\Delta$. Theorem~\ref{thm:no} marks
the sharp boundary: the elegance does not lift to the second order in
coefficient-only form.

Open directions include an \emph{index-dependent} discriminant polynomial
$\Delta_2(n)$ for second-order recurrences (reducing to $\gamma\beta-\alpha\delta$
when $r\equiv0$), tested against the Motzkin and Baxter numbers; a renormalization
tower dividing out the exact growth ratio to expose higher-order convexity toward
infinite log-concavity; and summation-by-parts refinements of the valuation decay
rate.

\section{Conclusion}

The M\"obius discriminant $\Delta=\gamma\beta-\alpha\delta$ decides, exactly and
pointwise, the log-behaviour of every sequence obeying a first-order
multiplicative recurrence: its sign fixes the log-convex/linear/concave
trichotomy and its value fixes the exact pointwise discriminant, the constant
numerator of the ratio's forward difference, and the closed-form log-curvature
that decays to zero. The phenomenon stops sharply at the second order, as
Cassini's identity for the Fibonacci numbers shows.

\end{document}

