"""Show that the forward difference of the growth ratio has the
constant numerator Delta (the Mobius rigidity)."""
from __future__ import annotations


def generate(alpha: float, beta: float, gamma: float, delta: float,
             a0: float, n_terms: int) -> list[float]:
    seq = [a0]
    for n in range(n_terms - 1):
        seq.append((gamma * n + delta) / (alpha * n + beta) * seq[-1])
    return seq


def recovered_delta(alpha: float, beta: float, gamma: float, delta: float,
                    a0: float, n: int) -> float:
    """Return (a(n+2)/a(n+1) - a(n+1)/a(n)) * (alpha n+beta)(alpha(n+1)+beta),
    which the theory predicts equals Delta = gamma*beta - alpha*delta."""
    seq = generate(alpha, beta, gamma, delta, a0, n + 3)
    diff = seq[n + 2] / seq[n + 1] - seq[n + 1] / seq[n]
    return diff * (alpha * n + beta) * (alpha * (n + 1) + beta)


if __name__ == "__main__":
    al, be, ga, de = 1.0, 2.0, 4.0, 2.0  # Catalan, Delta = 6
    for n in range(8):
        print(f"n={n}  recovered Delta = {recovered_delta(al, be, ga, de, 1.0, n):+.6f}")

"""Compare the measured log-curvature to its closed form and watch it decay."""
from __future__ import annotations

import math


def generate(alpha: float, beta: float, gamma: float, delta: float,
             a0: float, n_terms: int) -> list[float]:
    seq = [a0]
    for n in range(n_terms - 1):
        seq.append((gamma * n + delta) / (alpha * n + beta) * seq[-1])
    return seq


def measured_curvature(seq: list[float], n: int) -> float:
    return math.log(seq[n]) - 2 * math.log(seq[n + 1]) + math.log(seq[n + 2])


def closed_form_curvature(alpha: float, beta: float, gamma: float, delta: float,
                          n: int) -> float:
    d_val = gamma * beta - alpha * delta
    return math.log(1 + d_val / ((gamma * n + delta) * (alpha * (n + 1) + beta)))


if __name__ == "__main__":
    al, be, ga, de = 1.0, 2.0, 4.0, 2.0  # Catalan, Delta = 6
    seq = generate(al, be, ga, de, 1.0, 40)
    for n in [0, 1, 2, 4, 8, 16, 32]:
        m = measured_curvature(seq, n)
        c = closed_form_curvature(al, be, ga, de, n)
        print(f"n={n:2d}  measured={m:+.8f}  closed={c:+.8f}  diff={abs(m-c):.1e}")

