from __future__ import annotations


def classify(alpha: float, beta: float, gamma: float, delta: float) -> str:
    """Classify the log-behaviour of a first-order multiplicative recurrence."""
    delta_val: float = gamma * beta - alpha * delta
    if delta_val > 0:
        return "strictly log-convex"
    if delta_val < 0:
        return "strictly log-concave"
    return "log-linear"

