function RECOVER(a[0..N]):
    // model r(n) = a[n+1]/a[n] = (gamma*n + delta)/(alpha*n + beta)
    // with normalization; solve least squares for (alpha,beta,gamma,delta)
    build ratios r[n] = a[n+1]/a[n]
    set up equations r[n]*(alpha*n + beta) = gamma*n + delta
    solve linear system for (alpha, beta, gamma, delta)
    return (alpha, beta, gamma, delta, gamma*beta - alpha*delta)

